@import "tailwindcss";

@layer base {
  :root {
    --bg-dark: #040812;
    --bg-card: #080f1e;
    --accent-blue: #0ea5e9;
    --accent-cyan: #06b6d4;
    --accent-violet: #8b5cf6;
    --accent-indigo: #6366f1;
  }

  * {
    box-sizing: border-box;
  }

  html {
    direction: rtl;
    scroll-behavior: smooth;
  }

  body {
    background-color: #040812;
    color: #e2e8f0;
    font-family: 'Tajawal', 'Segoe UI', sans-serif;
    margin: 0;
    overflow-x: hidden;
  }

  h1, h2, h3, h4, h5, h6 {
    font-family: 'Tajawal', 'Segoe UI', sans-serif;
    font-weight: 700;
  }
}

/* Custom animations */
@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-20px); }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 20px rgba(14, 165, 233, 0.3); }
  50% { box-shadow: 0 0 60px rgba(14, 165, 233, 0.8), 0 0 100px rgba(139, 92, 246, 0.4); }
}

@keyframes gradient-shift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes scan-line {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(100vh); }
}

@keyframes data-flow {
  0% { stroke-dashoffset: 1000; opacity: 0; }
  50% { opacity: 1; }
  100% { stroke-dashoffset: 0; opacity: 0; }
}

@keyframes counter-up {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes rotate-slow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

.animate-float { animation: float 6s ease-in-out infinite; }
.animate-pulse-glow { animation: pulse-glow 3s ease-in-out infinite; }
.animate-gradient {
  background-size: 200% 200%;
  animation: gradient-shift 4s ease infinite;
}
.animate-rotate-slow { animation: rotate-slow 20s linear infinite; }
.animate-blink { animation: blink 1s step-end infinite; }

/* Gradient text */
.gradient-text {
  background: linear-gradient(135deg, #0ea5e9, #8b5cf6, #06b6d4);
  background-size: 200% 200%;
  animation: gradient-shift 4s ease infinite;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.gradient-text-gold {
  background: linear-gradient(135deg, #f59e0b, #fbbf24, #f97316);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Glass morphism */
.glass {
  background: rgba(8, 15, 30, 0.6);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(14, 165, 233, 0.15);
}

.glass-hover {
  transition: all 0.3s ease;
}

.glass-hover:hover {
  background: rgba(14, 165, 233, 0.08);
  border-color: rgba(14, 165, 233, 0.4);
  transform: translateY(-5px);
  box-shadow: 0 20px 60px rgba(14, 165, 233, 0.2);
}

/* Grid pattern */
.grid-pattern {
  background-image:
    linear-gradient(rgba(14, 165, 233, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(14, 165, 233, 0.05) 1px, transparent 1px);
  background-size: 60px 60px;
}

/* Neon border */
.neon-border {
  border: 1px solid transparent;
  background: linear-gradient(#040812, #040812) padding-box,
    linear-gradient(135deg, #0ea5e9, #8b5cf6) border-box;
}

.neon-border:hover {
  box-shadow: 0 0 30px rgba(14, 165, 233, 0.4), inset 0 0 30px rgba(14, 165, 233, 0.05);
}

/* Shimmer effect */
.shimmer::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.05), transparent);
  animation: shimmer 2s infinite;
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: #040812; }
::-webkit-scrollbar-thumb {
  background: linear-gradient(#0ea5e9, #8b5cf6);
  border-radius: 3px;
}

/* Section transitions */
.section-fade {
  opacity: 0;
  transform: translateY(40px);
  transition: all 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.section-fade.visible {
  opacity: 1;
  transform: translateY(0);
}

